#!/usr/bin/env python3
# FLOWPACK - FASE 5: CARTAO NFC (so Dono/Adm libera a emergencia)
# Uso:  python3 /root/instalar_fase5.py      (rode DEPOIS do instalar_fase4.py)
# Legenda:  ✅ aplicado   ⏭️  ja estava aplicado   ❌ nao deu (me mande a linha)
import os, sys, re, base64, shutil, subprocess, datetime
BASE = sys.argv[1] if len(sys.argv) > 1 else "/root/site_esteira"
SERVER = os.path.join(BASE, "server.js"); VIEWS = os.path.join(BASE, "views"); BASEHTML = os.path.join(VIEWS, "base.html")
BLOCO = base64.b64decode("").decode("utf-8"); ROTAS = base64.b64decode("").decode("utf-8"); PAGINA = base64.b64decode("").decode("utf-8")
for f in (SERVER, BASEHTML):
    if not os.path.exists(f): print("❌ Nao achei " + f); sys.exit(1)
c = open(SERVER, encoding="utf-8").read()
if "EMERGENCIA GLOBAL: depois de acionada" not in c: print("❌ A fase 4 (emergencia travada) ainda nao esta instalada. Rode primeiro o instalar_fase4.py."); sys.exit(1)
carimbo = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
for f in (SERVER, BASEHTML): shutil.copy2(f, f + ".bak_" + carimbo)
print("Copias de seguranca criadas (.bak_" + carimbo + ")\n"); res = []
destino = os.path.join(VIEWS, "nfc.html")
if os.path.exists(destino) and open(destino, encoding="utf-8").read() == PAGINA: res.append("⏭️  Pagina Cartoes NFC: ja estava atualizada.")
else: open(destino, "w", encoding="utf-8").write(PAGINA); res.append("✅ Pagina Cartoes NFC: gravada.")
def aplicar(nome, marcador, fn):
    global c
    if marcador in c: res.append("⏭️  %s: ja estava aplicado." % nome); return
    try: novo = fn(c)
    except Exception as e: res.append("❌ %s: %s" % (nome, e)); return
    if novo == c: res.append("❌ %s: trecho nao encontrado." % nome); return
    c = novo; res.append("✅ %s: aplicado." % nome)
def unico(t, a):
    if t.count(a) != 1: raise Exception("trecho nao encontrado (%d vezes)" % t.count(a))
def f_bloco(t):
    a = "    return mqttPublicarOriginal(topico, mensagem, ...resto);\n};"; unico(t, a); return t.replace(a, a + "\n" + BLOCO, 1)
def f_rotas(t):
    a = "app.get('/api/emergencia', loginObrigatorio, (req, res) => res.json(emergenciaGlobal));"; unico(t, a); return t.replace(a, a + "\n" + ROTAS, 1)
def f_sub(t):
    a = "mqttClient.subscribe(['esteira/estado_emergencia']);"; unico(t, a); return t.replace(a, a + "\n    mqttClient.subscribe(['nfc/leitura', 'nfc/status']);", 1)
def f_msg(t):
    a = "if (topic === 'esteira/estado_emergencia') emergenciaTratarEsteira(valor);"; unico(t, a); return t.replace(a, a + "\n    if (topic.startsWith('nfc/')) nfcTratarMqtt(topic, valor);", 1)
def f_lib(t):
    a = "app.post('/api/emergencia/liberar', loginObrigatorio, (req, res) => {"; unico(t, a); return t.replace(a, "app.post('/api/emergencia/liberar', loginObrigatorio, adminObrigatorio, (req, res) => {", 1)
def f_sis(t):
    a = "{ id: 'camera', nome: 'Camera', online: !!cameraOnline }"; unico(t, a); return t.replace(a, a + ",\n                { id: 'nfc', nome: 'Leitor NFC', online: !!nfcOnline }", 1)
aplicar("Servidor: cartoes NFC (leitura, cadastro, resposta ao buzzer)", "CARTOES NFC: so cartao de DONO", f_bloco)
aplicar("Servidor: rotas e tela dos cartoes", "/api/nfc/estado", f_rotas)
aplicar("Servidor: inscricao MQTT do leitor", "mqttClient.subscribe(['nfc/leitura'", f_sub)
aplicar("Servidor: tratamento MQTT do leitor", "nfcTratarMqtt(topic, valor);", f_msg)
aplicar("Emergencia: SO Dono ou Adm liberam pelo site", "'/api/emergencia/liberar', loginObrigatorio, adminObrigatorio", f_lib)
aplicar("Status do Sistema: mostra o leitor NFC", "nome: 'Leitor NFC'", f_sis)
open(SERVER, "w", encoding="utf-8").write(c)
b = open(BASEHTML, encoding="utf-8").read()
alerta = "if (!r.ok) { alert('Não foi possível liberar a emergência.'); return; }"
if alerta in b: b = b.replace(alerta, "if (!r.ok) { alert(r.status === 403 ? 'Somente Dono ou Adm podem liberar a emergência.' : 'Não foi possível liberar a emergência.'); return; }", 1); res.append("✅ Tela: aviso claro quando um Operário tenta liberar.")
else: res.append("⏭️  Tela: aviso de liberacao ja ajustado (ou fase 4 em outro formato).")
if 'id="link-nfc"' in b: res.append("⏭️  Menu: Cartoes NFC ja existia.")
else:
    m = re.search(r'<a href="/sistema"[\s\S]*?</a>\s*\{% endif %\}', b) or re.search(r'<a href="/controle"[\s\S]*?</a>\s*\{% endif %\}', b)
    link = """
                {% if isAdmin %}
                <a href="/nfc" data-spa-link class="flex items-center gap-3 px-4 py-3.5 sm:py-3 rounded-lg text-sm font-medium transition hover:bg-gray-50 active:bg-gray-100 text-gray-600" id="link-nfc">
                    <svg class="w-5 h-5 shrink-0" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="6" width="18" height="12" rx="2"/><path d="M8 12h.01M12 12h.01M16 12h.01"/></svg>
                    Cartões NFC
                </a>
                {% endif %}"""
    if m: b = b[:m.end()] + link + b[m.end():]; res.append("✅ Menu: Cartoes NFC adicionado (so Adm/Dono).")
    else: res.append("❌ Menu: nao achei onde colocar o item.")
if "'/nfc') idAlvo" in b: res.append("⏭️  Menu: destaque do item atual ja aplicado.")
else:
    a = "else if (caminho === '/dispenser') idAlvo = 'link-dispenser';"
    if b.count(a) == 1: b = b.replace(a, a + "\n                else if (caminho === '/nfc') idAlvo = 'link-nfc';", 1); res.append("✅ Menu: destaque do item atual aplicado.")
    else: res.append("❌ Menu: nao achei o trecho do destaque.")
open(BASEHTML, "w", encoding="utf-8").write(b)
print("\n".join(res)); print()
ok = subprocess.run(["node", "-c", SERVER], capture_output=True, text=True)
if ok.returncode == 0: print("✅ server.js sem erro de sintaxe.")
else: print("❌ ERRO DE SINTAXE:"); print(ok.stderr); print("Para voltar:  cp " + SERVER + ".bak_" + carimbo + " " + SERVER); sys.exit(1)
print("⚠️  Teve ❌ acima. Me mande essas linhas." if any(l.startswith("❌") for l in res) else "\nTudo certo! Reinicie:  sudo systemctl restart site_esteira   (depois Ctrl+Shift+R)")
